/// <summary>
/// GUPPricingAttribute of table <c>InventTableModule</c> field MultiLineDisc.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTableModule, MultiLineDisc))]
internal class GUPPricingAttributeInventTableModuleSalesMultiLineDisc extends GUPPricingAttributeInventTableModuleSales implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return strFmt("%1 - %2", enum2Str(ModuleInventPurchSales::Sales), fieldPName(InventTableModule, MultiLineDisc));
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, MultiLineDisc));
    qbr.value(queryValue(_value));
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTableModule   inventTableModule;
    PriceDiscGroup      priceDiscGroup;                 

    while select MultiLineDisc from inventTableModule
        join priceDiscGroup
        group by GroupId, Name, Module, Type
        where inventTableModule.MultiLineDisc == priceDiscGroup.GroupId 
            && InventTablemodule.ModuleType == ModuleInventPurchSales::Sales
            && priceDiscGroup.Module  == ModuleInventCustVend::Invent 
            && priceDiscGroup.Type == PriceGroupType::MultiLineDiscGroup
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(priceDiscGroup.GroupId, priceDiscGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
